const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries (points with 1km buffer)
  const reykjavik = ee.Geometry.Point([-21.9426, 64.1466]).buffer(1000); // 1km buffer
  const grindavik = ee.Geometry.Point([-22.4333, 63.8424]).buffer(1000);

  // 2. Define date
  const date = '2024-11-21';
  const startDate = ee.Date(date);
  const endDate = startDate.advance(1, 'day');

  // 3. Try to get VIIRS daily image
  let collection = ee.ImageCollection('NOAA/VIIRS/001/VNP46A2')
    .filterDate(startDate, endDate);

  // Check if collection is empty
  let size = collection.size().getInfo();
  if (size === 0) {
    // Try NOAA-20 collection
    collection = ee.ImageCollection('NOAA/VIIRS/001/VJ146A2')
      .filterDate(startDate, endDate);
    size = collection.size().getInfo();
    if (size === 0) {
      console.log(`No VIIRS images found for ${date}.`);
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Get the first image
  const image = collection.first();

  // 4. Mask clouds using quality band (QF_VNP46A2 or QF_VJ146A2)
  // Bits 0-1: Cloud mask (0=clear, 1=probably clear, 2=probably cloudy, 3=cloudy)
  // Keep clear (0) and probably clear (1)
  const qaBand = image.select('QF_VNP46A2').or(image.select('QF_VJ146A2'));
  const cloudMask = qaBand.bitwiseAnd(3).lte(1); // 0 or 1

  // Select the corrected NTL band (exists in both collections)
  const ntlBand = image.select('Gap_Filled_DNB_BRDF-Corrected_NTL');
  const maskedNTL = ntlBand.updateMask(cloudMask);

  // 5. Extract statistics for both locations
  const scale = 1000; // 1km scale for VIIRS
  const maxPixels = 1e9;

  const reykjavikStats = maskedNTL.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: reykjavik,
    scale: scale,
    maxPixels: maxPixels,
    bestEffort: true
  });

  const grindavikStats = maskedNTL.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: grindavik,
    scale: scale,
    maxPixels: maxPixels,
    bestEffort: true
  });

  // Get values
  const reykjavikMean = reykjavikStats.get('Gap_Filled_DNB_BRDF-Corrected_NTL_mean').getInfo();
  const reykjavikCount = reykjavikStats.get('Gap_Filled_DNB_BRDF-Corrected_NTL_count').getInfo();
  const grindavikMean = grindavikStats.get('Gap_Filled_DNB_BRDF-Corrected_NTL_mean').getInfo();
  const grindavikCount = grindavikStats.get('Gap_Filled_DNB_BRDF-Corrected_NTL_count').getInfo();

  // 6. Check for valid pixels
  if (reykjavikCount === 0 || grindavikCount === 0) {
    console.log(`Reykjavik pixels: ${reykjavikCount}, Grindavik pixels: ${grindavikCount}`);
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Check for valid values (not null/NaN and within reasonable range)
  const isValid = (val) => val !== null && !isNaN(val) && val >= 0 && val < 1000; // Upper bound check

  if (!isValid(reykjavikMean) || !isValid(grindavikMean)) {
    console.log(`Reykjavik mean: ${reykjavikMean}, Grindavik mean: ${grindavikMean}`);
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Compare and output
  console.log(`Reykjavik: ${reykjavikMean.toFixed(4)} (${reykjavikCount} px)`);
  console.log(`Grindavik: ${grindavikMean.toFixed(4)} (${grindavikCount} px)`);

  if (grindavikMean > reykjavikMean) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
